#import "TFAIWebSettings.h"
#import "TFAIUIHelpers.h"
#import "../Tools/TFAIWebTools.h"
@interface TFAIWebSettings : UITableViewController
@property UISwitch *enabled;
@end
@implementation TFAIWebSettings
- (void)viewDidLoad{[super viewDidLoad];self.title=@"联网检索";self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=64;}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 3;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?1:s==1?2:1;}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return @[@"网页与搜索",@"搜索服务",@"GitHub"][s];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return @[@"普通会话和项目会话均可只读检索。搜索词和指定链接会发送给相应网站，读取的正文会交给当前模型。网页不执行 JavaScript，也不共享登录 Cookie。下载资源、修改项目仍遵循原权限设置。",@"DuckDuckGo 无需密钥，可能出现验证或限流；可选 Brave Search API。密钥仅保存在本机钥匙串，不交给模型。",@"公开仓库搜索、读取文件、Issue 和 Release 可不填令牌；GitHub 代码搜索需要令牌。仅用于 api.github.com 的只读请求，不复用项目 Git 认证。令牌权限与账号额度由 GitHub 控制。"][s];}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{if(i.section==0){UITableViewCell *c=AICell(@"允许 AI 联网检索",@"网页读取、网络搜索、GitHub 查询",@"globe");self.enabled=[UISwitch new];self.enabled.on=TFAIWebTools.enabled;[self.enabled addTarget:self action:@selector(toggle:) forControlEvents:UIControlEventValueChanged];c.accessoryView=self.enabled;return c;}NSString *account=i.section==2?@"github":@"brave";BOOL provider=i.section==1&&i.row==0;NSString *detail=provider?([[NSUserDefaults.standardUserDefaults stringForKey:@"TFAI.Web.SearchProvider"] isEqual:@"brave"]?@"Brave Search API":@"DuckDuckGo"):[TFAIWebTools secret:account].length?@"已保存 · 点击修改或移除":@"未配置 · 点击添加";UITableViewCell *c=AICell(provider?@"搜索引擎":i.section==2?@"GitHub 令牌":@"Brave API 密钥",detail,provider?@"magnifyingglass":@"key");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;}
- (void)toggle:(UISwitch *)s{[NSUserDefaults.standardUserDefaults setBool:s.on forKey:@"TFAI.Web.Enabled"];}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(i.section==0)return;if(i.section==1&&i.row==0){UIAlertController *a=[UIAlertController alertControllerWithTitle:@"搜索引擎" message:nil preferredStyle:UIAlertControllerStyleActionSheet];for(NSArray *p in @[@[@"duckduckgo",@"DuckDuckGo"],@[@"brave",@"Brave Search API"]])[a addAction:[UIAlertAction actionWithTitle:p[1] style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){[NSUserDefaults.standardUserDefaults setObject:p[0] forKey:@"TFAI.Web.SearchProvider"];[t reloadData];}]];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];a.popoverPresentationController.sourceView=[t cellForRowAtIndexPath:i];[self presentViewController:a animated:YES completion:nil];return;}NSString *account=i.section==2?@"github":@"brave";UIAlertController *a=[UIAlertController alertControllerWithTitle:i.section==2?@"GitHub 令牌":@"Brave API 密钥" message:@"输入新密钥替换；留空保存将移除。" preferredStyle:UIAlertControllerStyleAlert];[a addTextFieldWithConfigurationHandler:^(UITextField *f){f.secureTextEntry=YES;f.placeholder=@"输入密钥";f.autocorrectionType=UITextAutocorrectionTypeNo;f.autocapitalizationType=UITextAutocapitalizationTypeNone;}];[a addAction:[UIAlertAction actionWithTitle:@"取消" style:UIAlertActionStyleCancel handler:nil]];[a addAction:[UIAlertAction actionWithTitle:@"保存" style:UIAlertActionStyleDefault handler:^(UIAlertAction *x){NSError *e=nil;if(![TFAIWebTools setSecret:[a.textFields.firstObject.text stringByTrimmingCharactersInSet:NSCharacterSet.whitespaceAndNewlineCharacterSet] account:account error:&e])AIAlert(self,@"保存失败",e.localizedDescription);[t reloadData];}]];[self presentViewController:a animated:YES completion:nil];}
@end
UIViewController *TFAIWebSettingsController(void){return [[TFAIWebSettings alloc]initWithStyle:UITableViewStyleInsetGrouped];}
